package com.hermes.backend.training;

import com.hermes.backend.runner.*;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import java.util.*;
import java.util.function.Supplier;
import static com.hermes.backend.training.TrainingStore.*;
import static com.hermes.backend.training.TrainingFailure.check;

@RestController @RequestMapping("/api/training")
@ConditionalOnProperty(name="app.training-workspace.enabled",havingValue="true")
public class TrainingController {
    final TrainingStore db;final TrainingAccess acl;final TrainingAthletes athletes;final TrainingTeams teams;final TrainingLibrary library;final TrainingBulk bulk;final TrainingMessages messages;final TrainingJobs jobs;final AccountDeletionService deletion;final AccountExportService exports;
    public TrainingController(TrainingStore db,TrainingAccess acl,TrainingAthletes athletes,TrainingTeams teams,TrainingLibrary library,TrainingBulk bulk,TrainingMessages messages,TrainingJobs jobs,AccountDeletionService deletion,AccountExportService exports){this.db=db;this.acl=acl;this.athletes=athletes;this.teams=teams;this.library=library;this.bulk=bulk;this.messages=messages;this.jobs=jobs;this.deletion=deletion;this.exports=exports;}
    String actor(Runner r){check(r!=null&&!r.isDeleted(),401,"SIGN_IN_REQUIRED");return db.ensure(r.getId(),r.getDisplayName(),r.getTimeZone());}
    long revision(String header){try{check(header!=null,428,"REVISION_REQUIRED");long value=Long.parseLong(header.replace("\"",""));check(value>=1,422,"INVALID_REVISION");return value;}catch(NumberFormatException invalid){throw new TrainingFailure(422,"INVALID_REVISION");}}
    Map<String,Object> command(String actor,String operation,String key,Map<String,Object> body,Runnable guard,Supplier<Map<String,Object>> work){return db.command(actor,operation,key,body,guard,work);}
    @GetMapping("/me") public Map<String,Object> me(@AuthenticationPrincipal Runner r){return athletes.me(actor(r));}
    @PatchMapping("/me") public Map<String,Object> profile(@AuthenticationPrincipal Runner r,@RequestHeader(value="If-Match",required=false)String match,@RequestBody Map<String,Object> body){return athletes.profile(actor(r),body,revision(match));}
    @GetMapping("/roster") public Map<String,Object> roster(@AuthenticationPrincipal Runner r,@RequestParam(required=false)String q){return athletes.roster(actor(r),q,false);}
    @GetMapping("/athletes/search") public Map<String,Object> search(@AuthenticationPrincipal Runner r,@RequestParam(required=false)String q){check(q==null||q.length()<=160,422,"QUERY_LIMIT");return athletes.roster(actor(r),q,true);}
    @GetMapping("/athletes/{aid}/activities") public Map<String,Object> activities(@AuthenticationPrincipal Runner r,@PathVariable String aid){return athletes.list(actor(r),id(aid));}
    @GetMapping("/activities/{activity}") public Map<String,Object> activity(@AuthenticationPrincipal Runner r,@PathVariable String activity){return athletes.detail(actor(r),id(activity));}
    @GetMapping("/activities/by-canonical/{canonicalId}") public Map<String,Object> canonicalActivity(@AuthenticationPrincipal Runner r,@PathVariable long canonicalId){return athletes.fromCanonical(actor(r),canonicalId);}
    @PostMapping("/athletes/{aid}/activities/manual") public Map<String,Object> manual(@AuthenticationPrincipal Runner r,@PathVariable String aid,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Map<String,Object> body){String actor=actor(r);return command(actor,"MANUAL:"+id(aid),key,body,()->{db.lock(aid);acl.require(actor,aid,true,null);},()->athletes.manual(actor,aid,body));}
    @PatchMapping("/activities/{activity}") public Map<String,Object> effort(@AuthenticationPrincipal Runner r,@PathVariable String activity,@RequestHeader(value="If-Match",required=false)String match,@RequestBody Map<String,Object> body){return athletes.effort(actor(r),id(activity),body,revision(match));}
    @SuppressWarnings("unchecked") @PutMapping("/activities/{activity}/intervals") public Map<String,Object> intervals(@AuthenticationPrincipal Runner r,@PathVariable String activity,@RequestHeader(value="If-Match",required=false)String match,@RequestBody Map<String,Object> body){fields(body,"intervals");check(body.get("intervals") instanceof List<?>,422,"INTERVALS_REQUIRED");return athletes.intervals(actor(r),id(activity),(List<Map<String,Object>>)body.get("intervals"),revision(match));}
    @GetMapping("/athletes/{aid}/calendar") public Map<String,Object> calendar(@AuthenticationPrincipal Runner r,@PathVariable String aid,@RequestParam(required=false)String start,@RequestParam(required=false)String end){return athletes.calendar(actor(r),id(aid),start,end);}
    @PostMapping("/athletes/{aid}/events") public Map<String,Object> event(@AuthenticationPrincipal Runner r,@PathVariable String aid,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Map<String,Object> body){String actor=actor(r);return command(actor,"EVENT:"+id(aid),key,body,()->{db.lock(aid);acl.require(actor,aid,true,null);},()->{
        // If a saved workout is selected, use its immutable server snapshot rather than client totals.
        var input=new LinkedHashMap<>(body);if(body.get("snapshot") instanceof Map<?,?> snapshot){check(snapshot.get("source") instanceof String,422,"WORKOUT_SOURCE_REQUIRED");var compiled=TrainingWorkout.compile((String)snapshot.get("source"));input.remove("snapshot");input.put("source",snapshot.get("source"));input.put("minutes",compiled.get("minutes"));input.remove("projectedLoad");}if(body.get("workoutId") instanceof String wid){var version=(int)number(body,"sourceVersion",1,100000);var w=library.workout(actor,wid,version);for(String field:List.of("title","minutes","source","sport"))input.put(field,w.get(field));input.remove("projectedLoad");}return athletes.event(actor,aid,input);
    });}
    @PatchMapping("/events/{event}") public Map<String,Object> change(@AuthenticationPrincipal Runner r,@PathVariable String event,@RequestHeader(value="If-Match",required=false)String match,@RequestBody Map<String,Object> body){return athletes.change(actor(r),id(event),body,revision(match));}
    @PostMapping("/events/{event}/completion") public Map<String,Object> completion(@AuthenticationPrincipal Runner r,@PathVariable String event,@RequestHeader(value="If-Match",required=false)String match,@RequestBody Map<String,Object> body){fields(body,"activityId");return athletes.link(actor(r),id(event),id(text(body,"activityId",36)),revision(match));}
    @GetMapping("/athletes/{aid}/fitness") public Map<String,Object> fitness(@AuthenticationPrincipal Runner r,@PathVariable String aid,@RequestParam(required=false)String start,@RequestParam(required=false)String end){return athletes.fitness(actor(r),id(aid),start,end);}
    @GetMapping("/athletes/{aid}/wellness") public Map<String,Object> wellness(@AuthenticationPrincipal Runner r,@PathVariable String aid){return athletes.wellness(actor(r),id(aid));}
    @PutMapping("/athletes/{aid}/wellness/{date}") public Map<String,Object> saveWellness(@AuthenticationPrincipal Runner r,@PathVariable String aid,@PathVariable String date,@RequestHeader(value="If-Match",required=false)String match,@RequestBody Map<String,Object> body){return athletes.saveWellness(actor(r),id(aid),date,body,match==null?null:revision(match));}
    @GetMapping("/workouts") public Map<String,Object> workouts(@AuthenticationPrincipal Runner r){return map("items",library.list(actor(r)).get("workouts"));}
    @GetMapping("/folders") public Map<String,Object> folders(@AuthenticationPrincipal Runner r){return map("items",library.list(actor(r)).get("folders"));}
    @GetMapping("/plans") public Map<String,Object> plans(@AuthenticationPrincipal Runner r){return map("items",library.list(actor(r)).get("plans"));}
    @PostMapping("/folders") public Map<String,Object> folder(@AuthenticationPrincipal Runner r,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Map<String,Object> body){fields(body,"name");String actor=actor(r);return command(actor,"FOLDER",key,body,()->{},()->library.folder(actor,text(body,"name",160)));}
    @PostMapping("/workouts") public Map<String,Object> workout(@AuthenticationPrincipal Runner r,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Map<String,Object> body){String actor=actor(r);return command(actor,"WORKOUT",key,body,()->{},()->library.saveWorkout(actor,null,body,null));}
    @PostMapping("/workouts/{workout}/versions") public Map<String,Object> workoutVersion(@AuthenticationPrincipal Runner r,@PathVariable String workout,@RequestHeader(value="If-Match",required=false)String match,@RequestBody Map<String,Object> body){return library.saveWorkout(actor(r),id(workout),body,revision(match));}
    @PostMapping("/plans") public Map<String,Object> plan(@AuthenticationPrincipal Runner r,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Map<String,Object> body){String actor=actor(r);return command(actor,"PLAN",key,body,()->{},()->library.savePlan(actor,body));}
    @PostMapping("/library-shares") public Map<String,Object> share(@AuthenticationPrincipal Runner r,@RequestBody Map<String,Object> body){fields(body,"type","resourceId","granteeId");return library.share(actor(r),text(body,"type",8),text(body,"resourceId",36),text(body,"granteeId",36));}
    @PostMapping("/plans/{plan}/applications/preview") public Map<String,Object> preview(@AuthenticationPrincipal Runner r,@PathVariable String plan,@RequestBody Map<String,Object> body){var input=new LinkedHashMap<>(body);input.put("planId",id(plan));return bulk.preview(actor(r),"plan",input);}
    @PostMapping("/configuration-previews") public Map<String,Object> configuration(@AuthenticationPrincipal Runner r,@RequestBody Map<String,Object> body){return bulk.preview(actor(r),"configuration",body);}
    @PostMapping("/bulk-operations/{operation}/commit") public Map<String,Object> commit(@AuthenticationPrincipal Runner r,@PathVariable String operation,@RequestBody Map<String,Object> body){fields(body,"hash");return bulk.commit(actor(r),id(operation),text(body,"hash",64));}
    @GetMapping("/me/access-requests") public Map<String,Object> requests(@AuthenticationPrincipal Runner r){return acl.requests(actor(r));}
    @GetMapping("/me/access") public Map<String,Object> access(@AuthenticationPrincipal Runner r){return acl.grants(actor(r));}
    @PostMapping("/athletes/{aid}/access-requests") public Map<String,Object> request(@AuthenticationPrincipal Runner r,@PathVariable String aid,@RequestBody Map<String,Object> body){fields(body,"level","wellness");return acl.request(actor(r),id(aid),text(body,"level",8),body.containsKey("wellness")?stringList(body.get("wellness")):List.of());}
    @PostMapping("/access-relationships/{relationship}/decision") public Map<String,Object> decide(@AuthenticationPrincipal Runner r,@PathVariable String relationship,@RequestBody Map<String,Object> body){fields(body,"decision","wellness");return acl.decide(actor(r),id(relationship),text(body,"decision",16),body.containsKey("wellness")?stringList(body.get("wellness")):null);}
    @PostMapping("/me/access/revoke-all") public Map<String,Object> revoke(@AuthenticationPrincipal Runner r,@RequestBody Map<String,Object> body){fields(body);return acl.revokeAll(actor(r));}
    @GetMapping("/teams") public Map<String,Object> teams(@AuthenticationPrincipal Runner r){return teams.list(actor(r));}
    @PostMapping("/teams") public Map<String,Object> createTeam(@AuthenticationPrincipal Runner r,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Map<String,Object> body){fields(body,"name");String actor=actor(r);return command(actor,"TEAM",key,body,()->{},()->{var t=teams.create(actor,text(body,"name",160));messages.open(actor,map("kind","group","teamId",t.get("id")));return t;});}
    @GetMapping("/teams/by-slug/{slug}") public Map<String,Object> joinCard(@AuthenticationPrincipal Runner r,@PathVariable String slug){actor(r);return teams.joinCard(id(slug));}
    @PatchMapping("/teams/{team}") public Map<String,Object> team(@AuthenticationPrincipal Runner r,@PathVariable String team,@RequestHeader(value="If-Match",required=false)String match,@RequestBody Map<String,Object> body){return teams.update(actor(r),id(team),body,revision(match));}
    @PatchMapping("/teams/{team}/members/{user}") public Map<String,Object> member(@AuthenticationPrincipal Runner r,@PathVariable String team,@PathVariable String user,@RequestBody Map<String,Object> body){fields(body,"role");return teams.member(actor(r),id(team),id(user),text(body,"role",8));}
    @PostMapping("/teams/{team}/join-requests") public Map<String,Object> join(@AuthenticationPrincipal Runner r,@PathVariable String team,@RequestBody Map<String,Object> body){fields(body);return teams.join(actor(r),id(team));}
    @PutMapping("/teams/{team}/consent") public Map<String,Object> consent(@AuthenticationPrincipal Runner r,@PathVariable String team,@RequestBody Map<String,Object> body){fields(body,"decision","scopeRevision","level","wellness");return teams.consent(actor(r),id(team),text(body,"decision",8),(long)number(body,"scopeRevision",1,Long.MAX_VALUE),text(body,"level",8),stringList(body.getOrDefault("wellness",List.of())));}
    @GetMapping("/conversations") public Map<String,Object> conversations(@AuthenticationPrincipal Runner r){return messages.list(actor(r));}
    @PostMapping("/conversations") public Map<String,Object> conversation(@AuthenticationPrincipal Runner r,@RequestBody Map<String,Object> body){return messages.open(actor(r),body);}
    @GetMapping("/conversations/{conversation}/messages") public Map<String,Object> messages(@AuthenticationPrincipal Runner r,@PathVariable String conversation){return messages.messages(actor(r),id(conversation));}
    @PostMapping("/conversations/{conversation}/messages") public Map<String,Object> send(@AuthenticationPrincipal Runner r,@PathVariable String conversation,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Map<String,Object> body){String actor=actor(r);return command(actor,"MSG:"+id(conversation),key,body,()->messages.require(actor,conversation,true),()->messages.send(actor,conversation,body));}
    @PostMapping(path="/imports",consumes="multipart/form-data") public Map<String,Object> upload(@AuthenticationPrincipal Runner r,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestParam MultipartFile file)throws java.io.IOException{check(file.getSize()>0&&file.getSize()<=20*1024*1024,413,"UPLOAD_SIZE_LIMIT");return jobs.enqueue(actor(r),file.getOriginalFilename(),file.getBytes(),key);}
    @GetMapping("/jobs/{job}") public Map<String,Object> job(@AuthenticationPrincipal Runner r,@PathVariable String job){return jobs.status(actor(r),id(job));}
    @DeleteMapping("/jobs/{job}") public Map<String,Object> cancel(@AuthenticationPrincipal Runner r,@PathVariable String job){return jobs.cancel(actor(r),id(job));}
    @GetMapping("/connections") public Map<String,Object> connections(@AuthenticationPrincipal Runner r){actor(r);return map("items",List.of(),"message","Providers require an approved application and your own keys; none is enabled by this module.");}
    @GetMapping("/comparisons") public Map<String,Object> comparisons(@AuthenticationPrincipal Runner r){String actor=actor(r);return map("items",db.rows("select * from tw_comparison where owner_id=? order by id fetch first 200 rows only",actor).stream().map(row->{var payload=db.object(row.get("payload"));for(String activity:stringList(payload.get("activityIds")))athletes.detail(actor,activity);payload.put("id",row.get("id"));return payload;}).toList());}
    @PostMapping("/comparisons") public Map<String,Object> comparison(@AuthenticationPrincipal Runner r,@RequestBody Map<String,Object> body){fields(body,"name","activityIds","offset");String actor=actor(r);return db.atomic(()->{String title=text(body,"name",160);var ids=stringList(body.get("activityIds"));check(!ids.isEmpty()&&ids.size()<=8,422,"COMPARISON_LIMIT");for(String activity:ids)athletes.detail(actor,activity);String id=uuid();var payload=map("name",title,"activityIds",ids,"offset",body.containsKey("offset")?number(body,"offset",0,5000):0);db.jdbc.update("insert into tw_comparison(id,owner_id,payload) values(?,?,?)",id,actor,db.encode(payload));payload.put("id",id);return payload;});}
    @GetMapping("/athletes/{aid}/season-plans") public Map<String,Object> seasons(@AuthenticationPrincipal Runner r,@PathVariable String aid){String actor=actor(r);return db.atomic(()->{db.lock(id(aid));acl.require(actor,aid,false,null);return map("items",db.rows("select * from tw_season where athlete_id=? order by id fetch first 100 rows only",aid).stream().map(row->{var p=db.object(row.get("payload"));p.put("id",row.get("id"));return p;}).toList());});}
    @PostMapping("/athletes/{aid}/season-plans") public Map<String,Object> season(@AuthenticationPrincipal Runner r,@PathVariable String aid,@RequestBody Map<String,Object> body){fields(body,"name","start","end","weeklyMinutes");String actor=actor(r);return db.atomic(()->{db.lock(id(aid));acl.require(actor,aid,true,null);String start=TrainingBulk.date(text(body,"start",10)),end=TrainingBulk.date(text(body,"end",10));check(end.compareTo(start)>=0,422,"INVALID_SEASON_RANGE");var p=map("name",text(body,"name",160),"start",start,"end",end,"weeklyMinutes",number(body,"weeklyMinutes",0,10080));String id=uuid();db.jdbc.update("insert into tw_season(id,athlete_id,payload) values(?,?,?)",id,aid,db.encode(p));db.touch(aid);p.put("id",id);return p;});}
    @GetMapping("/me/export") public void export(@AuthenticationPrincipal Runner r,HttpServletResponse response)throws java.io.IOException{actor(r);check(exports.tryBegin(),429,"EXPORT_BUSY");try{response.setContentType("application/zip");response.setHeader("Content-Disposition","attachment; filename=\"training-account.zip\"");exports.write(r,false,response.getOutputStream());response.flushBuffer();}finally{exports.end();}}
    @DeleteMapping("/me") public Map<String,Object> delete(@AuthenticationPrincipal Runner r,@RequestBody Map<String,Object> body){fields(body,"confirmation");String actor=actor(r);check("DELETE".equals(body.get("confirmation")),422,"CONFIRMATION_REQUIRED");deletion.deleteAccount(db.runner(actor));return map("deleted",true);}
    static List<String> stringList(Object input){check(input instanceof List<?> list&&list.size()<=50&&list.stream().allMatch(v->v instanceof String),422,"INVALID_LIST");return ((List<?>)input).stream().map(String.class::cast).toList();}
}
